    )

def test_tampered_signature_returns_false(self):
    bundle = sealed_bundle(self.key, self.records, 3, seed=7200)
    # A valid R of a different real round is still a subgroup element,
    # so the check runs and returns False rather than raising.
    other_message, _ = make_proof(self.records[:3], 1)
    other_signature = sign_message(self.key, other_message, seed=7210)
    tampered = AuditProofBundle(
        bundle.proof,
        AggregateSignature(
            R=other_signature.R,
            z=bundle.signature.z,
            signer_ids=bundle.signature.signer_ids,
        ),
    )
    self.assertFalse(
        verify_audit_proof_bundle(tampered, self.key)
    )

